struct Reference {
    bool applicable=false;
    bool mixed=false;
    int frequencyThousandths=-1;
    int referenceBB=0;
    const char* referencePosition="";
    const char* status="unavailable";
};
inline int handClassIndex(const KibitzerPreflopRanges::Hand& h) {
    if (h.hi<2 || h.lo<2 || h.hi>14 || h.lo>14 ||
        h.hi<h.lo) return -1;
    if (h.pair) return h.hi==h.lo ? 14-h.hi : -1;
    if (h.hi==h.lo) return -1;
    int offset=0;
    for (int rank=14;rank>h.hi;--rank) offset+=rank-2;
    offset+=h.hi-h.lo-1;
    return (h.suited?13:91)+offset;
}
inline int positionIndex(int alive,int roleIndex) {
    if (alive!=6 && alive!=8 && alive!=9) return -1;
    if (roleIndex<0 || roleIndex>=alive) return -1;
    if (roleIndex==0) return 0; // BTN
    if (roleIndex==1) return 1; // SB
    if (roleIndex==2) return -1; // BB never first-in open
    // Source uses EP1,EP2,EP3,LJ,HJ,CO; choose no unsupported
    // "seven handed" intermediate by interpolation.
    const int index=9-(alive-roleIndex);
    return index>=3 && index<=8 ? index : -1;
}
inline Reference lookup(int card0,int card1,int alive,int roleIndex,
                        double stackBB,bool facingRaise,int limpers,
                        int opponentAllIns) {
    Reference r;
    if (facingRaise||limpers>0||opponentAllIns>0) {
        r.status="contested-pot-not-comparable"; return r;
    }
    const int pos=positionIndex(alive,roleIndex);
    if (pos<0) { r.status="table-geometry-not-comparable";return r; }
    if (!std::isfinite(stackBB)||stackBB<=0) {
        r.status="invalid-stack-depth";return r;
    }
    const int cls=handClassIndex(KibitzerPreflopRanges::decode(card0,card1));
    if (cls<0){r.status="invalid-cards";return r;}
    int best=-1;double delta=1e100;
    for(int i=0;i<5;++i){
        const double d=std::abs(stackBB-kDepths[i]);
        if(d<delta){delta=d;best=i;}
    }
    r.referenceBB=kDepths[best];r.referencePosition=kPositions[pos];
    // Strict close match, not a blind nearest-neighbour extrapolation.
    if(delta>std::max(0.25,0.05*double(kDepths[best]))) {
        r.status="stack-depth-not-comparable";return r;
    }
    r.applicable=true;
    r.frequencyThousandths=kOpens[best][pos][cls];
    r.mixed=r.frequencyThousandths>0 && r.frequencyThousandths<1000;
    r.status="external-opening-chart-reference";
    return r;
}
